head.script:

scwin.onpageload = function() {
	var jsonData = [{},{},{}];
	dl_gridViewData.setJSON(jsonData);

	var selData1 = [{"col1":"상품","col2":"md"},{"col1":"주문","col2":"or"},{"col1":"채널","col2":"ch"}];
	dl_select1.setJSON(selData1);

	var selData2 = [{"col1":"상품","col2":"itm","col3":"md"}
					,{"col1":"협력사","col2":"ptn","col3":"md"}
					,{"col1":"대형제휴","col2":"b2b","col3":"md"}
					,{"col1":"프로모션","col2":"pmt","col3":"md"}
					,{"col1":"매퍼","col2":"map","col3":"md"}

					,{"col1":"고객","col2":"cst","col3":"or"}
					,{"col1":"주문","col2":"ord","col3":"or"}
					,{"col1":"결제","col2":"pay","col3":"or"}

					,{"col1":"방송","col2":"bcs","col3":"ch"}
					,{"col1":"온에어","col2":"bom","col3":"ch"}
					,{"col1":"타사모니터","col2":"bcm","col3":"ch"}
					,{"col1":"매체","col2":"pfm","col3":"ch"}];
	dl_select2.setJSON(selData2);
};

scwin.onpageunload = function() {

};


scwin.gridView1_onbeforeedit = function(row,col,value) {

};

scwin.gridView1_onafteredit = function(row,col,value) {
	var colId = gridView1.getColumnID(col);
	//시스템서비스구분은 시스템구분에 따라 변경
	if(colId == "col3") {
		var cnt = dl_select2.getRowCount();
		var sysGbCd = dl_gridViewData.getCellData(row, "col3");
		for(var i = 0 ; i < cnt ; i++){
			var cdGrp = dl_select2.getCellData(i, "col3");
			dl_select2.setCellData(i, "useYn", (sysGbCd == cdGrp) ? true : false);
		}

		console.log( dl_gridViewData.getCellData(row, "col3") );
		var temp = dl_select2.getMatchedJSON("useYn", true);
		console.dir( temp );

		dl_gridViewData.setCellData(row, "col4", temp[0].col2);
		gridView1.setColumnVisibleColumn("col4", "useYn", false);
	}
};

scwin.Dbclick = function(id) {
	var el = WebSquare.wUnit.getDomById(id);
	scwin.fireDbClick(el);
}
scwin.fireDbClick = function(node) {
	if (document.createEventObject) {
		node.fireEvent('ondblclick');
	} else if (document.createEvent) {
		var evt = document.createEvent('MouseEvents');
		evt.initEvent('dblclick', true, false);
		node.dispatchEvent(evt);
	} else if (typeof node.ondblclick == 'function') {
		node.ondblclick();
	}
}	
scwin.checkVal = function() {
	return WebSquare.wUnit.getJq('#G_gridView1___selectbox_col4_itemTable').height() > 0;
}
scwin.unitTest = function() {
	//Unit test
	WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "scwin.Dbclick('gridView1_cell_0_2')");
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('G_gridView1___selectbox_col3_itemTable_1').click()");
	WebSquare.wUnit.addCommand("pause", "400");			
	WebSquare.wUnit.addCommand("set", "scwin.Dbclick('gridView1_cell_0_3')");
	WebSquare.wUnit.addCommand("pause", "400");
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
	WebSquare.wUnit.addCommand("pause", "300");
	//Run and Stop test
	WebSquare.wUnit.run();
	WebSquare.wUnit.stop();
}
scwin.unitTest()
